fn decode_cyclic(s: &Vec<i8>) -> Vec<i8> {
    let L = s.len();
    let P = L - (L % 3);
    let mut res = Vec::with_capacity(L);

    for i in 0..P {
        match i % 3 {
            0 => res.push(s[i + 2]),
            1 => res.push(s[i - 1]),
            2 => res.push(s[i]), // unchanged for i%3 == 2
            _ => unreachable!(),  // defensive, though modulo 3 only 0,1,2
        }
    }

    // copy remaining elements unchanged
    for i in P..L {
        res.push(s[i]);
    }

    res
}